<template><section class="pro-panel"><div class="pro-section-head"><div><span class="eyebrow">Settled record</span><h1>Prediction Results</h1><p>Review how your published selections have been settled.</p></div></div><div class="td-kpis"><div class="td-kpi"><span>Won</span><b>{{won}}</b></div><div class="td-kpi"><span>Lost</span><b>{{lost}}</b></div><div class="td-kpi"><span>Void</span><b>{{voided}}</b></div><div class="td-kpi"><span>Open / pending</span><b>{{open}}</b></div></div><div v-if="settled.length" class="td-table"><div class="td-table-head"><span>Fixture</span><span>Selection</span><span>Odds</span><span>Result</span></div><div v-for="p in settled" :key="p._id" class="td-table-row"><div><b>{{p.fixture||'Football match'}}</b><small>{{formatDate(p.createdAt)}}</small></div><span>{{p.prediction}}</span><strong>{{Number(p.odds||0).toFixed(2)}}</strong><em :class="'td-status-pill '+p.status">{{p.status}}</em></div></div><div v-else class="empty">No settled prediction results yet.</div></section></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../services/api';import{formatDate}from'../utils/formatters';const predictions=ref<any[]>([]);const settled=computed(()=>predictions.value.filter(x=>['won','lost','void'].includes(x.status)));const won=computed(()=>predictions.value.filter(x=>x.status==='won').length),lost=computed(()=>predictions.value.filter(x=>x.status==='lost').length),voided=computed(()=>predictions.value.filter(x=>x.status==='void').length),open=computed(()=>predictions.value.filter(x=>!['won','lost','void'].includes(x.status)).length);onMounted(async()=>{try{predictions.value=(await api.get('/me/tipster')).data.predictions||[]}catch{}})</script>
